# We also verify that the instance is nontrivial: at least 3 distinct nontrivial radicands and A0 not an integer.
from math import isqrt
from fractions import Fraction

def choose(n, k):
    if k < 0 or k > n:
        return 0
    # simple integer binomial
    num = 1
    den = 1
    k = min(k, n - k)
    for i in range(1, k + 1):
        num *= n - k + i
        den *= i
    return num // den

def M(d, r, s, t):
    # count ordered pairs (u, w) with |u|=r, |w|=s, |u∩w|=t among d coordinates
    # M = C(d, t) * C(d - t, r - t) * C(d - r, s - t) subject to feasibility
    if t < 0 or t > r or t > s:
        return 0
    if r < 0 or s < 0 or r > d or s > d:
        return 0
    if r + s - t > d:
        return 0
    return choose(d, t) * choose(d - t, r - t) * choose(d - r, s - t)

def squarefree_part(n):
    # return sf, c such that n = c^2 * sf, with sf squarefree
    sf = n
    p = 2
    while p * p <= sf:
        sq = p * p
        while sf % sq == 0:
            sf //= sq
        p += 1
    m = n // sf
    c = isqrt(m)
    # assert c*c == m
    return sf, c

def analyze_instance(d, L):
    coeff_base = Fraction(L * L, 12)
    A0 = Fraction(0, 1)
    rad_map = {}  # sf -> Fraction coef
