                W = M(d, r, s, t) * (1 << (d - (r + s - t)))
                contrib = coeff_base * W * c
                if sf == 1:
                    A0 += contrib
                else:
                    rad_map[sf] = rad_map.get(sf, Fraction(0, 1)) + contrib
    return A0, rad_map

